private static void markDeposit(char[][] grid, int row, int col) {
    if (row < 0 || row >= grid.length || col < 0 || col >= grid[row].length || grid[row][col] != '@') {
        return;
    }

    grid[row][col] = '*'; // Mark as visited

    // Check all 8 possible directions
    markDeposit(grid, row - 1, col - 1); // top-left
    markDeposit(grid, row - 1, col);     // top
    markDeposit(grid, row - 1, col + 1); // top-right
    markDeposit(grid, row, col - 1);     // left
    markDeposit(grid, row, col + 1);     // right
    markDeposit(grid, row + 1, col - 1); // bottom-left
    markDeposit(grid, row + 1, col);     // bottom
    markDeposit(grid, row + 1, col + 1); // bottom-right
}
