public static int maxRegions(int N) {
    if (N == 0) return 1;
    if (N == 1) return 2;
    int regions = 2;
    int additionalRegions = 2;
    for (int i = 1; i < N; i++) {
        additionalRegions += i + 1;
        regions += additionalRegions;
    }
    return regions;
}

