public static int maxRegions(int N) {
    if (N == 0) return 1;
    if (N == 1) return 2;

    int[] regions = new int[N + 1];
    regions[0] = 1;
    regions[1] = 2;

    for (int i = 2; i <= N; i++) {
        regions[i] = regions[i - 1] + 3 * (i - 1) + 1;
    }

    return regions[N];
