public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    return canTravel(n, start[0], start[1], end[0], end[1], paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravel(int n, int currentX, int currentY, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (currentX == endX && currentY == endY) {
        return true;
    }

    visited[currentX][currentY] = true;

    for (int[] path : paths) {
        if (path[0] == currentX && path[1] == currentY && !visited[path[2]][path[3]] &&
            canTravel(n, path[2], path[3], endX, endY, paths, visited)) {
            return true;
        }
        if (path[2] == currentX && path[3] == currentY && !visited[path[0]][path[1]] &&
            canTravel(n, path[0], path[1], endX, endY, paths, visited)) {
            return true;
        }
    }

    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    return canTravelMazeHelper(start[0], start[1], end[0], end[1], paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravelMazeHelper(int x, int y, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (x == endX && y == endY) {
        return true;
    }
    visited[x][y] = true;
    for (int[] path : paths) {
        int newX = path[0] == x && path[1] == y ? path[2] : path[0] == x && path[2] == y ? path[1] : -1;
        int newY = path[1] == y && path[2] == x ? path[0] : path[2] == y && path[1] == x ? path[0] : -1;
        if (newX != -1 && newY != -1 && !visited[newX][newY] && canTravelMazeHelper(newX, newY, endX, endY, paths, visited)) {
            return true;
        }
    }
    return false;
}

