private static boolean dfs(int x, int y, int ex, int ey, boolean[][] visited, int[][] paths, int n) {
    if (x == ex && y == ey) return true;
    if (x < 0 || x >= n || y < 0 || y >= n || visited[x][y]) return false;

    visited[x][y] = true;

    for (int[] path : paths) {
        int dx = path[0];
        int dy = path[1];
        if (dfs(x + dx, y + dy, ex, ey, visited, paths, n)) {
            return true;
        }
    }

    return false;
}

