    for (char c : word1.toCharArray()) {
        count1[c - 'A']++;
    }

    for (char c : word2.toCharArray()) {
        count2[c - 'A']++;
    }

    int common = 0;
    for (int i = 0; i < 26; i++) {
        common += Math.min(count1[i], count2[i]);
    }

    int totalLength = word1.length() + word2.length();
    int gcd = gcd(common, totalLength);

    return String.format("appx(%s, %s) = %d/%d", word1, word2, common / gcd, totalLength / gcd);
}

