    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (!used[j] && word1.charAt(i) == word2.charAt(j)) {
                commonCount++;
                used[j] = true;
                break;
            }
        }
    }

    // Calculate the total length
