    // Reduce the fraction
    int gcd = gcd(commonCount, totalLength);
    int reducedNumerator = commonCount / gcd;
    int reducedDenominator = totalLength / gcd;

    // Return the result as a string
    return "appx(" + word1 + ", " + word2 + ") = " + (reducedDenominator == 1 ? reducedNumerator : reducedNumerator + "/" + reducedDenominator);
}

