public static String convertDatesToWeekdays(String date) {
    String[] months = {"January", "February", "March", "April", "May", "June", 
                        "July", "August", "September", "October", "November", "December"};
    String[] days = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

    String[] parts = date.split(" ");
    int month = Integer.parseInt(parts[0]) - 1;
    int day = Integer.parseInt(parts[1]);
    int year = Integer.parseInt(parts[2]);

    // Zeller's Congruence Algorithm to find the day of the week
    int q = day; // day of the month
    int m = month + 1; // month (3 = March, 4 = April, 5 = May, ..., 12 = December, 1 = January, 2 = February)
    int K = year % 100; // year of the century (year % 100)
    int J = year / 100; // zero-based century (year / 100)

    if (m < 3) {
        m += 12;
        K -= 1;
    }

    int f = q + 13 * (m + 1) / 5 + K + K / 4 + J / 4 + 5 * J;
    int h = f % 7; // 0 = Saturday, 1 = Sunday, 2 = Monday, ..., 6 = Friday

    // Adjust h to match the days array (0 = Sunday, 1 = Monday, ..., 6 = Saturday)
    h = (h + 5) % 7;

    return months[month] + " " + day + ", " + year + " is a " + days[h];
}

