public double trimMean(int[] arr) {
    int n = arr.length;
    int cut = n / 20; // 5% of the elements
    Arrays.sort(arr);
    int sum = 0;
    for (int i = cut; i < n - cut; i++) {
        sum += arr[i];
    }
    return (double) sum / (n - 2 * cut);
}

