    for (int[] edge : edges) {
        adjList.get(edge[0]).add(edge[1]);
        adjList.get(edge[1]).add(edge[0]);
    }
    return dfs(0, -1, adjList, hasApple);
}

private int dfs(int node, int parent, List<List<Integer>> adjList, boolean[] hasApple) {
    int totalTime = 0;
    for (int neighbor : adjList.get(node)) {
        if (neighbor == parent) continue;
        int timeFromChild = dfs(neighbor, node, adjList, hasApple);
        if (timeFromChild > 0 || hasApple[neighbor]) {
            totalTime += timeFromChild + 2; // 2 for round trip
        }
    }
    return totalTime;
}

