public boolean splitArraySameAverage(int[] nums) {
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    int n = nums.length;
    boolean[][][] dp = new boolean[n + 1][n / 2 + 1][totalSum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = Math.min(i - 1, n / 2); j >= 1; j--) {
            for (int k = 0; k <= totalSum; k++) {
                dp[i][j][k] = dp[i - 1][j][k];
                if (!dp[i][j][k] && k >= num) {
                    dp[i][j][k] = dp[i - 1][j - 1][k - num];
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (totalSum * i % n == 0 && dp[n][i][totalSum * i / n]) {
            return true;
        }
    }
    return false;
}

