    }

    boolean[][][] dp = new boolean[n / 2 + 1][n + 1][sum + 1];
    dp[0][0][0] = true;

    for (int i = 0; i < n; i++) {
        for (int j = Math.min(i + 1, n / 2); j > 0; j--) {
            for (int k = 0; k <= sum; k++) {
                if (dp[j - 1][i][k]) {
                    dp[j][i + 1][k + nums[i]] = true;
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        for (int j = i; j <= n; j++) {
            if (dp[i][j][sum * i / j] && sum * i % j == 0) {
                return true;
            }
        }
    }

    return false;
}

