public boolean hasAllCodes(String s, int k) {
    if (s.length() < (1 << k) + k - 1) {
        return false;
    }

    Set<Integer> seen = new HashSet<>();
    int val = 0;
    int mask = (1 << k) - 1;

    for (int i = 0; i < s.length(); i++) {
        val = (val << 1) & mask | (s.charAt(i) - '0');
        if (i >= k - 1 && seen.add(val) && seen.size() == (1 << k)) {
            return true;
        }
    }

    return false;
}

public boolean hasAllCodes(String s, int k) {
    int need = 1 << k;
    boolean[] got = new boolean[need];
    int allOne = need - 1;
    int hashVal = 0;

    for (int i = 0; i < s.length(); i++) {
        hashVal = (hashVal << 1) & allOne | (s.charAt(i) - '0');
        if (i >= k - 1 && !got[hashVal]) {
            got[hashVal] = true;
            need--;
            if (need == 0) {
                return true;
            }
        }
    }
    return false;
}

public boolean hasAllCodes(String s, int k) {
    int total = 1 << k; // Total number of binary strings of length k
    boolean[] seen = new boolean[total];
    int num = 0;
    int mask = total - 1; // Mask to keep the last k bits

    for (int i = 0; i < s.length(); i++) {
        num = ((num << 1) & mask) | (s.charAt(i) - '0'); // Update the number with the new bit
        if (i >= k - 1 && !seen[num]) {
            seen[num] = true;
            total--;
            if (total == 0) {
                return true;
            }
        }
    }

    return false;
}

