public int minInsertions(String s) {
    int left = 0; // Unmatched '('
    int right = 0; // Required ')' to balance

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (right % 2 == 1) {
                // We need to insert a ')' to balance the last '('
                left++;
                right--;
            }
            right += 2;
        } else {
            right--;
            if (right == -1) {
                // We need to insert a '(' to balance this ')'
                left++;
                right = 1;
            }
        }
    }

    return left + right;
}

public int minInsertions(String s) {
    int leftBalance = 0; // Tracks the number of '(' left to balance
    int insertions = 0;  // Counts the number of insertions made

    for (char c : s.toCharArray()) {
        if (c == '(') {
            leftBalance++; // Increment balance for '('
        } else {
            if (leftBalance > 0) {
                leftBalance--; // Balance with a matching ')'
            } else {
                insertions++; // Need to insert a '(' to balance
            }
        }
    }

    // Each remaining '(' needs a closing ')'
    insertions += leftBalance;

    return insertions;
}

public int minInsertions(String s) {
    int openCount = 0;
    int insertions = 0;
    int i = 0;

    while (i < s.length()) {
        if (s.charAt(i) == '(') {
            openCount++;
            i++;
        } else {
            // Handle two consecutive ')'
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i += 2;
            } else {
                // Handle single ')'
                i++;
                insertions++;
            }

            // Need to balance with a '('
            if (openCount > 0) {
                openCount--;
            } else {
                insertions++;
            }
        }
    }

    // Each remaining open '(' needs a closing ')'
    insertions += openCount;

    return insertions;
}

public int minInsertions(String s) {
    int open = 0; // Counter for open parentheses '('
    int insertions = 0; // Counter for insertions needed

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            open++; // Increment open parenthesis counter
        } else {
            // For each ')', we need a matching '('
            if (open > 0) {
                open--; // Match with an open parenthesis
            } else {
                insertions++; // Need to insert a '('
            }
            // Check if the next character is also ')'
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next ')' as it is matched
            } else {
                insertions++; // Need to insert a ')'
            }
        }
    }

    // Add remaining open parentheses that need matching ')'
    insertions += open * 2;

    return insertions;
}

public int minInsertions(String s) {
    int left = 0; // Number of '(' needed
    int right = 0; // Number of ')' needed

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (right % 2 == 1) {
                // Unmatched ')'
                left++;
                right--;
            }
            right += 2; // Each '(' needs two ')'
        } else {
            right--;
            if (right == -1) {
                // Unmatched '('
                left++;
                right = 1; // Need one ')'
            }
        }
    }

    return left + right;
}

