public int maxUniqueSplit(String s) {
    return backtrack(s, new HashSet<>(), 0);
}

private int backtrack(String s, HashSet<String> set, int start) {
    if (start == s.length()) {
        return 0;
    }
    int max = 0;
    for (int end = start + 1; end <= s.length(); end++) {
        String substring = s.substring(start, end);
        if (!set.contains(substring)) {
            set.add(substring);
            max = Math.max(max, 1 + backtrack(s, set, end));
            set.remove(substring);
        }
    }
    return max;
}

public int maxUniqueSplit(String s) {
    return helper(s, new HashSet<>());
}

private int helper(String s, Set<String> used) {
    if (s.isEmpty()) {
        return 0;
    }
    int maxUnique = 0;
    for (int i = 1; i <= s.length(); i++) {
        String prefix = s.substring(0, i);
        if (!used.contains(prefix)) {
            used.add(prefix);
            maxUnique = Math.max(maxUnique, 1 + helper(s.substring(i), used));
            used.remove(prefix);
        }
    }
    return maxUnique;
}

