public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder(n);
    int totalValue = k - 1; // subtract n to account for 'a'
    for (int i = n - 1; i >= 0; i--) {
        int fillValue = Math.min(totalValue, 25); // 'z' - 'a'
        result.append((char) ('a' + fillValue));
        totalValue -= fillValue;
    }
    return result.reverse().toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (n > 0) {
        int remaining = k - 26 * (n - 1);
        if (remaining > 0) {
            char c = (char) (remaining - 1 + 'a');
            result.append(c);
            k -= remaining;
        } else {
            result.append('a');
            k -= 1;
        }
        n--;
    }
    return result.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < n; i++) {
        result.append('a');
    }
    k -= n;
    int i = n - 1;
    while (k > 0) {
        if (k >= 25) {
            result.setCharAt(i, 'z');
            k -= 25;
        } else {
            result.setCharAt(i, (char) ('a' + k));
            k = 0;
        }
        i--;
    }
    return result.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int remainingValue = k - n;

    for (int i = 0; i < n; i++) {
        if (remainingValue > 25) {
            result.append('z');
            remainingValue -= 25;
        } else {
            result.append((char) ('a' + remainingValue));
            remainingValue = 0;
        }
    }

    return result.reverse().toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int remainingValue = k;
    for (int i = 0; i < n; i++) {
        int remainingPositions = n - i - 1;
        // Fill the current position with the smallest possible character
        int charValue = Math.max(1, remainingValue - 26 * remainingPositions);
        result.append((char) (charValue + 'a' - 1));
        remainingValue -= charValue;
    }
    return result.toString();
}

