public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;

    Queue<Integer> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num > high) continue;
        if (num >= low) result.add(num);
        if (num == 0) continue;

        int lastDigit = num % 10;
        if (lastDigit > 0) {
            int nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) queue.offer(nextNum);
        }
        if (lastDigit < 9) {
            int nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) queue.offer(nextNum);
        }
    }

    Collections.sort(result);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;
    Queue<String> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        queue.offer(String.valueOf(i));
    }

    while (!queue.isEmpty()) {
        String numStr = queue.poll();
        if (!numStr.isEmpty()) {
            int num = Integer.parseInt(numStr);
            if (num >= low && num <= high) {
                result.add(num);
            }
            if (num == 0 || num > high) continue;
            int lastDigit = num % 10;
            if (lastDigit > 0) {
                queue.offer(numStr + (lastDigit - 1));
            }
            if (lastDigit < 9) {
                queue.offer(numStr + (lastDigit + 1));
            }
        }
    }

    Collections.sort(result);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;

    for (int i = 0; i <= 9; i++) {
        if (i >= low && i <= high) {
            result.add(i);
        }
        findSteppingNumbersHelper(i, i, low, high, result);
    }

    Collections.sort(result);
    return result;
}

private static void findSteppingNumbersHelper(int current, int lastDigit, int low, int high, List<Integer> result) {
    if (current > high) return;

    if (current >= low) {
        result.add(current);
    }

    if (lastDigit > 0) {
        findSteppingNumbersHelper(current * 10 + (lastDigit - 1), lastDigit - 1, low, high, result);
    }
    if (lastDigit < 9) {
        findSteppingNumbersHelper(current * 10 + (lastDigit + 1), lastDigit + 1, low, high, result);
    }
}

