public static int squarePermutations(int[] A) {
    boolean[] visited = new boolean[A.length];
    int[] count = new int[1];
    for (int i = 0; i < A.length; i++) {
        count[0] = 0;
        backtrack(A, visited, new int[A.length], 0, i, count);
    }
    return count[0];
}

private static void backtrack(int[] A, boolean[] visited, int[] path, int depth, int index, int[] count) {
    visited[index] = true;
    path[depth] = A[index];
    if (depth == A.length - 1) {
        count[0]++;
    } else {
        for (int i = 0; i < A.length; i++) {
            if (!visited[i] && isPerfectSquare(path[depth] + A[i])) {
                backtrack(A, visited, path, depth + 1, i, count);
            }
        }
    }
    visited[index] = false;
}

