private static int backtrack(int[] A, boolean[] used, StringBuilder path, int count) {
    if (path.length() == A.length * 2 - 1) {
        return 1;
    }

    int result = 0;
    for (int i = 0; i < A.length; i++) {
        if (!used[i]) {
            if (path.length() == 0 || isPerfectSquare(Integer.parseInt(path.substring(path.length() - 1)) + A[i])) {
                used[i] = true;
                path.append(A[i]);
                result += backtrack(A, used, path, count + 1);
                used[i] = false;
                path.setLength(path.length() - 1);
            }
        }
    }
    return result;
}

