private static void backtrack(List<List<Integer>> result, List<Integer> tempList, int[] A, boolean[] used) {
    if (tempList.size() == A.length) {
        result.add(new ArrayList<>(tempList));
    } else {
        for (int i = 0; i < A.length; i++) {
            if (used[i] || (i > 0 && A[i] == A[i - 1] && !used[i - 1])) continue;
            if (tempList.size() == 0 || isPerfectSquare(tempList.get(tempList.size() - 1) + A[i])) {
                used[i] = true;
                tempList.add(A[i]);
                backtrack(result, tempList, A, used);
                used[i] = false;
                tempList.remove(tempList.size() - 1);
            }
        }
    }
}

