private static void backtrack(int[] A, boolean[] used, int[] path, int depth, int[] count) {
    if (depth == A.length) {
        count[0]++;
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (!used[i]) {
            if (depth == 0 || isPerfectSquare(path[depth - 1] + A[i])) {
                used[i] = true;
                path[depth] = A[i];
                backtrack(A, used, path, depth + 1, count);
                used[i] = false;
            }
        }
    }
}

