private static void backtrack(int[] A, boolean[] used, List<Integer> path, int[] count) {
    if (path.size() == A.length) {
        count[0]++;
        return;
    }

    Set<Integer> uniqueNumbers = new HashSet<>();
    for (int i = 0; i < A.length; i++) {
        if (used[i] || (path.size() > 0 && uniqueNumbers.contains(A[i])))
            continue;

        if (path.isEmpty() || isPerfectSquare(path.get(path.size() - 1) + A[i])) {
            used[i] = true;
            path.add(A[i]);
            backtrack(A, used, path, count);
            path.remove(path.size() - 1);
            used[i] = false;
            uniqueNumbers.add(A[i]);
        }
    }
}

