public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    int maxArea = 0;

    // Fill left array with the index of the first bar to the left that is smaller than heights[i]
    Stack<Integer> stack = new Stack<>();
    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        left[i] = stack.isEmpty() ? -1 : stack.peek();
        stack.push(i);
    }

    // Clear the stack to reuse it
    stack.clear();

    // Fill right array with the index of the first bar to the right that is smaller than heights[i]
    for (int i = n - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        right[i] = stack.isEmpty() ? n : stack.peek();
        stack.push(i);
    }

    // Calculate the maximum area using the precomputed left and right indices
    for (int i = 0; i < n; i++) {
        int width = right[i] - left[i] - 1;
        int area = heights[i] * width;
        maxArea = Math.max(maxArea, area);
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    int[] stack = new int[heights.length];
    int top = -1;
    int i = 0;

    while (i < heights.length) {
        if (top == -1 || heights[i] >= heights[stack[top]]) {
            stack[++top] = i++;
        } else {
            int h = heights[stack[top--]];
            int left = top == -1 ? -1 : stack[top];
            maxArea = Math.max(maxArea, h * (i - left - 1));
        }
    }

    while (top != -1) {
        int h = heights[stack[top--]];
        int left = top == -1 ? -1 : stack[top];
        maxArea = Math.max(maxArea, h * (heights.length - left - 1));
    }

    return maxArea;
}

