    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the digits after (i+1)-th place
    StringBuilder sb = new StringBuilder();
    for (int k = 0; k <= i; k++) {
        sb.append(digits[k]);
